                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   response = awaitValue(this->v2PublicGetFuturesTicker(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->v2PublicGetSpotTicker(
                       this->extend(request, params)));
                 }
                 //
                 // Spot
