                 //                 "volume": "461.76557205",
                 //                 "volume_buy": "11.41506354",
                 //                 "volume_sell": "7.3240169"
                 //             }
                 //         ],
                 //         "message": "OK"
                 //     }
                 //
                 // Swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": [
                 //             {
                 //                 "close": "62480.08",
                 //                 "high": "64100",
                 //                 "index_price": "62443.05",
                 //                 "last": "62480.08",
                 //                 "low": "59600",
                 //                 "mark_price": "62443.05",
                 //                 "market": "BTCUSDT",
                 //                 "open": "61679.98",
                 //                 "period": 86400,
                 //                 "value": "180226025.69791713065326633165",
                 //                 "volume": "2900.2218",
                 //                 "volume_buy": "7.3847",
                 //                 "volume_sell": "6.1249"
                 //             }
                 //         ],
                 //         "message": "OK"
