  ccxt::any parsePosition(ccxt::any position,
                          ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "position_id": 305891033,
    //         "market": "BTCUSDT",
    //         "market_type": "FUTURES",
    //         "side": "long",
    //         "margin_mode": "cross",
    //         "open_interest": "0.0001",
    //         "close_avbl": "0.0001",
    //         "ath_position_amount": "0.0001",
    //         "unrealized_pnl": "0",
    //         "realized_pnl": "-0.00311684",
    //         "avg_entry_price": "62336.8",
    //         "cml_position_value": "6.23368",
    //         "max_position_value": "6.23368",
    //         "created_at": 1715152208041,
    //         "updated_at": 1715152208041,
    //         "take_profit_price": "0",
    //         "stop_loss_price": "0",
    //         "take_profit_type": "",
    //         "stop_loss_type": "",
    //         "settle_price": "62336.8",
    //         "settle_value": "6.23368",
    //         "leverage": "3",
    //         "margin_avbl": "2.07789333",
    //         "ath_margin_size": "2.07789333",
    //         "position_margin_rate": "2.40545879023305655728",
    //         "maintenance_margin_rate": "0.005",
    //         "maintenance_margin_value": "0.03118094",
    //         "liq_price": "0",
    //         "bkr_price": "0",
    //         "adl_level": 1
    //     }
    //
    ccxt::any marketId = this->safeString(position, std::string("market"));
    market =
        this->safeMarket(marketId, market, ccxt::any{}, std::string("swap"));
    ccxt::any timestamp =
        this->safeInteger(position, std::string("created_at"));
    return this->safePosition(ccxt::dict{
        {std::string("info"), position},
        {std::string("id"),
         this->safeInteger(position, std::string("position_id"))},
        {std::string("symbol"), ::getValue(market, std::string("symbol"))},
        {std::string("notional"),
         this->safeNumber(position, std::string("settle_value"))},
        {std::string("marginMode"),
         this->safeString(position, std::string("margin_mode"))},
        {std::string("liquidationPrice"),
         this->safeNumber(position, std::string("liq_price"))},
        {std::string("entryPrice"),
         this->safeNumber(position, std::string("avg_entry_price"))},
        {std::string("unrealizedPnl"),
         this->safeNumber(position, std::string("unrealized_pnl"))},
        {std::string("realizedPnl"),
         this->safeNumber(position, std::string("realized_pnl"))},
        {std::string("percentage"), ccxt::any{}},
        {std::string("contracts"),
         this->safeNumber(position, std::string("close_avbl"))},
        {std::string("contractSize"),
         this->safeNumber(market, std::string("contractSize"))},
        {std::string("markPrice"), ccxt::any{}},
        {std::string("lastPrice"), ccxt::any{}},
        {std::string("side"), this->safeString(position, std::string("side"))},
        {std::string("hedged"), ccxt::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("lastUpdateTimestamp"),
         this->safeInteger(position, std::string("updated_at"))},
        {std::string("maintenanceMargin"),
         this->safeNumber(position, std::string("maintenance_margin_value"))},
        {std::string("maintenanceMarginPercentage"),
         this->safeNumber(position, std::string("maintenance_margin_rate"))},
        {std::string("collateral"),
         this->safeNumber(position, std::string("margin_avbl"))},
        {std::string("initialMargin"), ccxt::any{}},
        {std::string("initialMarginPercentage"), ccxt::any{}},
        {std::string("leverage"),
         this->safeNumber(position, std::string("leverage"))},
        {std::string("marginRatio"),
         this->safeNumber(position, std::string("position_margin_rate"))},
        {std::string("stopLossPrice"),
         this->omitZero(
             this->safeString(position, std::string("stop_loss_price")))},
        {std::string("takeProfitPrice"),
         this->omitZero(
             this->safeString(position, std::string("take_profit_price")))},
    });
  }

  /**
   * @method
   * @name coinex#setMarginMode
   * @description set margin mode to 'cross' or 'isolated'
   * @see
   * https://docs.coinex.com/api/v2/futures/position/http/adjust-position-leverage
   * @param {string} marginMode 'cross' or 'isolated'
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} params.leverage the rate of leverage
   * @returns {object} response from the exchange
   */
  std::shared_future<ccxt::any>
  setMarginMode(ccxt::any marginMode, ccxt::any symbol = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " setMarginMode() requires a symbol argument"))));
                 }
                 marginMode = toLowerCase(marginMode);
                 if (isTrue(
                         isTrue(
                             !isEqual(marginMode, std::string("isolated"))) &&
                         isTrue(!isEqual(marginMode, std::string("cross"))))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" setMarginMode() marginMode argument "
                                       "should be isolated or cross"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("type")),
                                     std::string("swap")))) {
                   throw BadSymbol(toString(add(
                       this->id,
                       std::string(
                           " setMarginMode() supports swap contracts only"))));
                 }
                 ccxt::any leverage =
                     this->safeInteger(params, std::string("leverage"));
                 ccxt::any maxLeverage = this->safeInteger(
                     ::getValue(::getValue(market, std::string("limits")),
                                std::string("leverage")),
                     std::string("max"), 100);
                 if (isTrue(isEqual(leverage, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " setMarginMode() requires a leverage parameter"))));
                 }
                 if (isTrue(isTrue((isLessThan(leverage, 1))) ||
                            isTrue((isGreaterThan(leverage, maxLeverage))))) {
                   throw BadRequest(toString(
                       add(add(add(add(this->id,
                                       std::string(" setMarginMode() leverage "
                                                   "should be between 1 and ")),
                                   toString(maxLeverage)),
                               std::string(" for ")),
                           symbol)));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("market_type"), std::string("FUTURES")},
                     {std::string("margin_mode"), marginMode},
                     {std::string("leverage"), leverage},
                 };
                 return awaitValue(
                     this->v2PrivatePostFuturesAdjustPositionLeverage(
                         this->extend(request, params)));
               })
        .share();
  }

  /**
   * @method
   * @name coinex#setLeverage
   * @see
   * https://docs.coinex.com/api/v2/futures/position/http/adjust-position-leverage
   * @description set the level of leverage for a market
   * @param {float} leverage the rate of leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] 'cross' or 'isolated' (default is
   * 'cross')
   * @returns {object} response from the exchange
   */
  std::shared_future<ccxt::any>
  setLeverage(ccxt::any leverage, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " setLeverage() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("swap")),
                                     true))) {
                   throw BadSymbol(toString(add(
                       this->id,
                       std::string(
                           " setLeverage() supports swap contracts only"))));
                 }
                 ccxt::any marginMode = ccxt::any{};
                 ccxt::any marginModeparamsVariable =
                     this->handleMarginModeAndParams(std::string("setLeverage"),
                                                     params,
                                                     std::string("cross"));
                 marginMode = ::getValue(marginModeparamsVariable, 0);
                 params = ::getValue(marginModeparamsVariable, 1);
                 ccxt::any minLeverage = this->safeInteger(
                     ::getValue(::getValue(market, std::string("limits")),
                                std::string("leverage")),
                     std::string("min"), 1);
                 ccxt::any maxLeverage = this->safeInteger(
                     ::getValue(::getValue(market, std::string("limits")),
                                std::string("leverage")),
                     std::string("max"), 100);
                 if (isTrue(isTrue((isLessThan(leverage, minLeverage))) ||
                            isTrue((isGreaterThan(leverage, maxLeverage))))) {
                   throw BadRequest(toString(
                       add(add(add(add(add(add(this->id,
                                               std::string(
                                                   " setLeverage() leverage "
                                                   "should be between ")),
                                           toString(minLeverage)),
                                       std::string(" and ")),
                                   toString(maxLeverage)),
                               std::string(" for ")),
                           symbol)));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("market_type"), std::string("FUTURES")},
                     {std::string("margin_mode"), marginMode},
                     {std::string("leverage"), leverage},
                 };
                 return awaitValue(
                     this->v2PrivatePostFuturesAdjustPositionLeverage(
                         this->extend(request, params)));
               })
        .share();
  }

  /**
   * @method
   * @name coinex#fetchLeverageTiers
   * @description retrieve information on the maximum leverage, and maintenance
   * margin for trades of varying trade sizes
   * @see
   * https://docs.coinex.com/api/v2/futures/market/http/list-market-position-level
   * @param {string[]|undefined} symbols list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [leverage tiers structures]{@link
   * https://docs.ccxt.com/?id=leverage-tiers-structure}, indexed by market
   * symbols
   */
  std::shared_future<ccxt::any>
  fetchLeverageTiers(ccxt::any symbols = ccxt::any{},
                     ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any request = ccxt::dict{};
                        if (isTrue(!isEqual(symbols, ccxt::any{}))) {
                          ccxt::any marketIds = this->marketIds(symbols);
                          ::setValue(request, std::string("market"),
                                     join(marketIds, std::string(",")));
                        }
                        ccxt::any response =
                            awaitValue(this->v2PublicGetFuturesPositionLevel(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "code": 0,
                        //         "data": [
                        //             {
                        //                 "level": [
                        //                     {
                        //                         "amount": "20001",
                        //                         "leverage": "20",
                        //                         "maintenance_margin_rate":
                        //                         "0.02",
                        //                         "min_initial_margin_rate":
                        //                         "0.05"
                        //                     },
                        //                     {
                        //                         "amount": "50001",
                        //                         "leverage": "10",
                        //                         "maintenance_margin_rate":
                        //                         "0.04",
                        //                         "min_initial_margin_rate":
                        //                         "0.1"
                        //                     },
                        //                 ],
                        //                 "market": "MINAUSDT"
                        //             },
                        //         ],
                        //         "message": "OK"
                        //     }
                        //
                        ccxt::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseLeverageTiers(data, symbols,
                                                        std::string("market"));
                      })
        .share();
  }

  ccxt::any parseMarketLeverageTiers(ccxt::any info,
                                     ccxt::any market = ccxt::any{}) override {
    ccxt::any tiers = ccxt::list{};
    ccxt::any brackets =
        this->safeList(info, std::string("level"), ccxt::list{});
    ccxt::any minNotional = 0;
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(brackets));
         postFixIncrement(i)) {
      ccxt::any tier = ::getValue(brackets, i);
      ccxt::any marketId = this->safeString(info, std::string("market"));
      market =
          this->safeMarket(marketId, market, ccxt::any{}, std::string("swap"));
      ccxt::any maxNotional = this->safeNumber(tier, std::string("amount"));
      ccxt::any curr =
          (isTrue((isEqual(::getValue(market, std::string("linear")), true)))
               ? ccxt::any(::getValue(market, std::string("base")))
               : ccxt::any(::getValue(market, std::string("quote"))));
      ccxt::any notional = minNotional;
      arrayPush(
          tiers,
          ccxt::dict{
              {std::string("tier"), this->sum(i, 1)},
              {std::string("symbol"),
               this->safeSymbol(marketId, market, ccxt::any{},
                                std::string("swap"))},
              {std::string("currency"), curr},
              {std::string("minNotional"), notional},
              {std::string("maxNotional"), maxNotional},
              {std::string("maintenanceMarginRate"),
               this->safeNumber(tier, std::string("maintenance_margin_rate"))},
              {std::string("maxLeverage"),
               this->safeInteger(tier, std::string("leverage"))},
              {std::string("info"), tier},
          });
      minNotional = maxNotional;
    }
    return tiers;
  }

  virtual std::shared_future<ccxt::any>
  modifyMarginHelper(ccxt::any symbol, ccxt::any amount, ccxt::any addOrReduce,
                     ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any rawAmount = this->amountToPrecision(symbol, amount);
                 ccxt::any requestAmount = rawAmount;
                 if (isTrue(isEqual(addOrReduce, std::string("reduce")))) {
                   requestAmount = ccxt::Precise::stringNeg(rawAmount);
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("market_type"), std::string("FUTURES")},
                     {std::string("amount"), requestAmount},
                 };
                 ccxt::any response =
                     awaitValue(this->v2PrivatePostFuturesAdjustPositionMargin(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": 0,
                 //         "data": {
                 //             "adl_level": 1,
                 //             "ath_margin_size": "2.034928",
                 //             "ath_position_amount": "0.0001",
                 //             "avg_entry_price": "61047.84",
                 //             "bkr_price": "30698.5600000000000004142",
                 //             "close_avbl": "0.0001",
                 //             "cml_position_value": "6.104784",
                 //             "created_at": 1715488472908,
                 //             "leverage": "3",
                 //             "liq_price": "30852.82412060301507579316",
                 //             "maintenance_margin_rate": "0.005",
                 //             "maintenance_margin_value": "0.03051465",
                 //             "margin_avbl": "3.034928",
                 //             "margin_mode": "isolated",
                 //             "market": "BTCUSDT",
                 //             "market_type": "FUTURES",
                 //             "max_position_value": "6.104784",
                 //             "open_interest": "0.0001",
                 //             "position_id": 306458800,
                 //             "position_margin_rate":
                 //             "0.49713929272518077625", "realized_pnl":
                 //             "-0.003052392", "settle_price": "61047.84",
                 //             "settle_value": "6.104784",
                 //             "side": "long",
                 //             "stop_loss_price": "0",
                 //             "stop_loss_type": "",
                 //             "take_profit_price": "0",
                 //             "take_profit_type": "",
                 //             "unrealized_pnl": "0",
                 //             "updated_at": 1715488805563
                 //         },
                 //         "message": "OK"
                 //     }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any status =
                     this->safeStringLower(response, std::string("message"));
                 ccxt::any type =
                     (isTrue((isEqual(addOrReduce, std::string("reduce"))))
                          ? ccxt::any(std::string("reduce"))
                          : ccxt::any(std::string("add")));
                 return this->extend(
                     this->parseMarginModification(data, market),
                     ccxt::dict{
                         {std::string("type"), type},
                         {std::string("amount"), this->parseNumber(amount)},
                         {std::string("status"), status},
                     });
               })
        .share();
  }

  ccxt::any parseMarginModification(ccxt::any data,
                                    ccxt::any market = ccxt::any{}) override {
    //
    // addMargin/reduceMargin
    //
    //     {
    //         "adl_level": 1,
    //         "ath_margin_size": "2.034928",
    //         "ath_position_amount": "0.0001",
    //         "avg_entry_price": "61047.84",
    //         "bkr_price": "30698.5600000000000004142",
    //         "close_avbl": "0.0001",
    //         "cml_position_value": "6.104784",
    //         "created_at": 1715488472908,
    //         "leverage": "3",
    //         "liq_price": "30852.82412060301507579316",
    //         "maintenance_margin_rate": "0.005",
    //         "maintenance_margin_value": "0.03051465",
    //         "margin_avbl": "3.034928",
    //         "margin_mode": "isolated",
    //         "market": "BTCUSDT",
    //         "market_type": "FUTURES",
    //         "max_position_value": "6.104784",
    //         "open_interest": "0.0001",
    //         "position_id": 306458800,
    //         "position_margin_rate": "0.49713929272518077625",
    //         "realized_pnl": "-0.003052392",
    //         "settle_price": "61047.84",
    //         "settle_value": "6.104784",
    //         "side": "long",
    //         "stop_loss_price": "0",
    //         "stop_loss_type": "",
    //         "take_profit_price": "0",
    //         "take_profit_type": "",
    //         "unrealized_pnl": "0",
    //         "updated_at": 1715488805563
    //     }
    //
    // fetchMarginAdjustmentHistory
    //
    //     {
    //         "bkr_pirce": "24698.56000000000000005224",
    //         "created_at": 1715489978697,
    //         "leverage": "3",
    //         "liq_price": "24822.67336683417085432386",
    //         "margin_avbl": "3.634928",
    //         "margin_change": "-1.5",
    //         "margin_mode": "isolated",
    //         "market": "BTCUSDT",
    //         "market_type": "FUTURES",
    //         "open_interest": "0.0001",
    //         "position_id": 306458800,
    //         "settle_price": "61047.84"
    //     }
    //
    ccxt::any marketId = this->safeString(data, std::string("market"));
    ccxt::any timestamp = this->safeInteger2(data, std::string("updated_at"),
                                             std::string("created_at"));
    ccxt::any change = this->safeString(data, std::string("margin_change"));
    return ccxt::dict{
        {std::string("info"), data},
        {std::string("symbol"),
         this->safeSymbol(marketId, market, ccxt::any{}, std::string("swap"))},
        {std::string("type"), ccxt::any{}},
        {std::string("marginMode"), std::string("isolated")},
        {std::string("amount"),
         this->parseNumber(ccxt::Precise::stringAbs(change))},
        {std::string("total"),
         this->safeNumber(data, std::string("margin_avbl"))},
        {std::string("code"), this->safeString(market, std::string("quote"))},
        {std::string("status"), ccxt::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
  }

  /**
   * @method
   * @name coinex#addMargin
   * @description add margin
   * @see
   * https://docs.coinex.com/api/v2/futures/position/http/adjust-position-margin
   * @param {string} symbol unified market symbol
   * @param {float} amount amount of margin to add
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [margin structure]{@link
   * https://docs.ccxt.com/?id=margin-structure}
   */
  std::shared_future<ccxt::any>
  addMargin(ccxt::any symbol, ccxt::any amount,
            ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        return awaitValue(this->modifyMarginHelper(
                            symbol, amount, std::string("add"), params));
                      })
        .share();
  }

